def l_name_for_dynamic_library(libname: str, handle: ctypes.CDLL) -> str:
    lm_view = ctypes.POINTER(_LinkMapLNameView)()
    rc = LIBDL.dlinfo(ctypes.c_void_p(handle._handle), RTLD_DI_LINKMAP, ctypes.byref(lm_view))
    if rc != 0:
        err = _dl_last_error()
        raise OSError(f'dlinfo failed for libname={libname!r} (rc={rc})' + (f': {err}' if err else ''))
    else:
        if not lm_view:
            raise OSError(f'dlinfo returned NULL link_map pointer for libname={libname!r}')
        l_name_bytes = lm_view.contents.l_name
        if not l_name_bytes:
            raise OSError(f'dlinfo returned empty link_map->l_name for libname={libname!r}')
        path = os.fsdecode(l_name_bytes)
        if not path:
            raise OSError(f'dlinfo returned empty l_name string for libname={libname!r}')
        return path
```

